/*
* Componente principal de la aplicación
* Implementa:
* - Estructura general de la aplicación
* - Rutas principales
* - Gestión de autenticación a nivel global
*/

import React from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import { useAuth } from './contexts/AuthContext';
import './styles/App.css';

// Importar páginas principales
import LandingPage from './pages/LandingPage';
import LoginPage from './pages/LoginPage';
import RegisterPage from './pages/RegisterPage';
import MainMenuPage from './pages/MainMenuPage';
import GamePage from './pages/GamePage';
import CityPage from './pages/CityPage';
import HeroPage from './pages/HeroPage';

const App: React.FC = () => {
  const { isAuthenticated, loading } = useAuth();
  
  if (loading) {
    return <div className="loading-screen">Cargando...</div>;
  }

  return (
    <Router>
      <Routes>
        <Route path="/" element={<LandingPage />} />
        {/* Rutas públicas */}
        <Route path="/login" element={!isAuthenticated ? <LoginPage setAuth={() => {}} /> : <Navigate to="/menu" />} />
        <Route path="/register" element={!isAuthenticated ? <RegisterPage setAuth={() => {}} /> : <Navigate to="/menu" />} />
        
        {/* Rutas protegidas */}
        <Route path="/menu" element={isAuthenticated ? <MainMenuPage /> : <Navigate to="/login" />} />
        <Route path="/game/:gameId" element={isAuthenticated ? <GamePage /> : <Navigate to="/login" />} />
        <Route path="/city/:cityId" element={isAuthenticated ? <CityPage /> : <Navigate to="/login" />} />
        <Route path="/hero/:heroId" element={isAuthenticated ? <HeroPage /> : <Navigate to="/login" />} />
        
        {/* Ruta por defecto */}
        <Route path="*" element={<Navigate to={isAuthenticated ? "/menu" : "/login"} />} />
      </Routes>
    </Router>
  );
}

export default App;
